body {
    font-family: Arial, sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
    margin: 0;
}
.container {
    text-align: center;
}
input[type="number"] {
    padding: 8px;
    font-size: 16px;
}
button {
    padding: 10px 20px;
    font-size: 16px;
    cursor: pointer;
}
p {
    margin-top: 20px;
    font-size: 18px;
}

function calculateGasSplit() {
    const totalGas = parseFloat(document.getElementById('totalGas').value);
    const numCars = parseInt(document.getElementById('numCars').value);
    if (isNaN(totalGas) || isNaN(numCars)) {
        document.getElementById('result').innerText = 'Please enter valid numbers.';
        return;
    }
    const gasPerCar = totalGas / numCars;
    document.getElementById('result').innerText = gasPerCar.toFixed(2);
}

